interface Node { accept<R>(visitor: Visitor<R>): R }
interface Visitor<R> { visitLiteral(n: Literal): R; visitBinary(n: Binary): R }
class Literal implements Node { constructor(public value: number) {} accept(v: Visitor<any>) { return v.visitLiteral(this) } }
class Binary implements Node { constructor(public left: Node, public right: Node) {} accept(v: Visitor<any>) { return v.visitBinary(this) } }
class Eval implements Visitor<number> { visitLiteral(n: Literal) { return n.value } visitBinary(n: Binary) { return this.visitBinary(n) } }

